steps.script:
$o=@()
foreach($n in @('titulares.log','tendencias.log','ttittulares-mobile-trigger.log','ttendencias-mobile-trigger.log')){
 $p=Join-Path 'C:\TTiTTulares' $n
 if(-not(Test-Path $p)){$o+=@{name=$n;present=$false};continue}
 $l=@(Get-Content $p -Tail 180 -ErrorAction SilentlyContinue)
 $tags=@('TOO_MANY_TABS','EDITORIAL_TAB_SOFT_PRESSURE','MENSAJE ENVIADO','PREFLIGHT pages','OTHER_CHAT_ACTIVITY','TRANSMISSION_UNVERIFIED','EDITORIAL RETRY DEFERRED','ACK RUNNING','ACK FAILED','RUNNING','ERROR')
 $c=@{}
 foreach($tag in $tags){$c[$tag]=@($l|Where-Object{$_ -like ('*'+$tag+'*')}).Count}
 $o+=@{name=$n;updated=(Get-Item $p).LastWriteTimeUtc.ToString('o');counts=$c}
}
Write-Output ('TTRESULT:'+(@{logs=$o}|ConvertTo-Json -Compress -Depth 4))
